let raceSoundEnabled=false,raceSoundContext=null,lastSoundAt=-Infinity,raceSoundVolume=.5;
function raceCue(kind){
 if(!raceSoundEnabled)return;
 try{
  const Audio=window.AudioContext||window.webkitAudioContext;if(!Audio)return;
  if(!raceSoundContext)raceSoundContext=new Audio();
  if(raceSoundContext.state==='suspended')raceSoundContext.resume().catch(()=>{});
  const now=raceSoundContext.currentTime;if(now-lastSoundAt<.12)return;lastSoundAt=now;const notes={start:[480,620],zone:[530,690],pass:[650,850],incident:[340,230],finish:[740,940,1130],landing:[210,170],bite:[610,720],write:[310,390],idea:[740,1100],maze:[560,820],award:[740,940,1130]}[kind]||[520];
  notes.forEach((frequency,i)=>{const osc=raceSoundContext.createOscillator(),gain=raceSoundContext.createGain(),at=now+i*.075;osc.type='square';osc.frequency.setValueAtTime(frequency,at);gain.gain.setValueAtTime(.0001,at);gain.gain.linearRampToValueAtTime(.028*raceSoundVolume,at+.012);gain.gain.exponentialRampToValueAtTime(.0001,at+.065);osc.connect(gain);gain.connect(raceSoundContext.destination);osc.start(at);osc.stop(at+.07);});
 }catch{/* Browsers without sound permission keep text/visuals fully usable. */}
}
function stopRace(){if(raceTimer){clearInterval(raceTimer);raceTimer=null;}if(raceAnimationFrame!==null){window.cancelAnimationFrame?.(raceAnimationFrame);raceAnimationFrame=null;}}
function closeModal(){stopRace();$('game').hidden=false;modalType='';$('modal-root').innerHTML='';document.body.style.overflow='';previousFocus?.isConnected&&previousFocus.focus();}
