const practiceOf=s=>({ability:s.stats[4],luck:(Math.imul(s.turn+1,0x9e3779b1)^(s.seed||0))>>>0,lost:s.lastAction?.outcome==='failure'});
// #30 (owner 2026-10-26 「選択肢選ぶとすぐに結果じゃなくて話終わってから結果出す」): the reply after a choice is
