function title(){const art=heroSheet("./assets/title-v22/zodiac-challenge-v22.png");return `<section class="title-screen title-cover panel"><div class="title-backdrop" aria-hidden="true" style="background-image:url('${art}')"></div><button class="title-help" data-action="help"><span aria-hidden="true">?</span> あそびかた</button><div class="title-copy"><h1>はむちゅたーGP<br><span>〜十二支決定戦〜</span></h1><p>あの日、目の前を駆けたネズミの背中。<br>こんどは、同じスタートラインへ。</p></div><figure class="title-visual"><img class="title-keyart" src="${art}" width="1448" height="1086" alt="ひまわりの道を走るもちまる・ダッシュ・はかせ。神社の向こうには、憧れのネズミと十二支の強豪たち。" decoding="async" fetchpriority="high"></figure><div class="title-buttons">${s.phase==='select'?button('choose','はむちゅたーをえらぶ →'):button('continue','育成のつづきから →')}${button('album','図鑑','secondary')}${button('archive','育成記録','secondary')}${s.phase!=='select'?button('restart','新しい育成をはじめる','secondary'):''}</div></section><section class="intro-cards"><p><b>育てる</b>いっしょに練習して、強くなる。</p><p><b>勝ち抜く</b>50→25→12→代表1匹。</p><p><b>憧れへ</b>世界50種の中で、12位以内をめざす。</p></section>`;}
