function roadmap(){const competitions=isLegacy(s)?[]:Object.values(COMPETITIONS).filter(c=>c.kind!=='repechage').sort((a,b)=>a.turn-b.turn||(a.kind==='zodiac'?1:-1)),goal=s.storyVersion===3?yearGoal(s):null;return `<section class="roadmap">${goal?`<div class="year-goal"><b>${goal.year}年目の目標</b><p>${goal.goal}</p><small>壁：${goal.wall}</small></div>`:''}<h3>十二支への道のり</h3>${competitions.map((c,i)=>{const r=s.races.find(r=>r.competitionId===c.id);return `<div class="road-step ${r?'done':s.pendingCompetitionId===c.id?'current':''}"><span class="step-icon">${r?'✓':i+1}</span><div><strong>${c.title}</strong><small>${c.turn}ターン / ${c.entrants}匹 ${r?` · ${r.rank}位`:c.cutoff?` · 上位${c.cutoff}匹`:''}</small></div></div>`;}).join('')}<p class="goal-note">通常3大会＋年度末3大会。<br>1・2年目だけ、直後の敗者復活あり。</p></section>`;}
function raceReady(){const c=currentCompetition(s),course=currentCourse(s),legacy=isLegacy(s),style=STYLES[s.pendingStyle];
 const rule=c.kind==='zodiac'?'50種類の代表。上位12種が、新しい十二支。':c.kind==='repechage'?`予選落ち全員で争い、上位${c.cutoff}匹が復活枠へ。負ければ育成終了。`:c.cutoff?`${c.entrants}匹で競い、上位${c.cutoff}匹が直接通過。${c.year===3?'復活なし、一発勝負。':`残る${c.revivalSlots}枠は直後の復活戦。`}`:'勝っても負けても、育成はつづく。';
 const zones=legacy?'旧版のコースを維持します。':s.scouted.includes(c.id)?'下見で確認：'+(course.zones.map(x=>({maze:'迷路',eating:'早食い',study:'勉強'}[x])).join(' → ')||'特殊ゾーンなし'):'特殊ゾーンはスタート後に公開。';
 return `<section class="race-ready race-one"><div class="race-one-head"><span class="eyebrow">RACE DAY · ${c.entrants}匹</span><h2>${normal(c.title)}</h2></div><p class="race-one-rule">${rule}</p><p class="race-one-course"><b>${course.name}</b> ${zones}</p>${legacy?(c.courseIds?`<div class="course-picker">${c.courseIds.map(id=>`<button class="course-option" data-course="${id}">${id==='sprint'?'かけっこ':id==='eating'?'早食い':'勉強・迷路'}</button>`).join('')}</div>`:''):`<fieldset class="style-picker"><legend>走り方を決めよう</legend>${Object.entries(STYLES).map(([id,x])=>`<button class="course-option ${s.pendingStyle===id?'selected':''}" data-style="${id}" aria-pressed="${s.pendingStyle===id}"><b>${x.name}</b></button>`).join('')}</fieldset><p class="race-one-style">${style?esc(style.description):''} 注目：${c.kind==='zodiac'?'ネズミ':'同じ個体たちが成長中'}</p>`}${button('race','レースを見守る →','primary full')}</section>`;}
