// One-screen home (#30, owner 2026-10-25 after playing on a phone): no scrolling. A thin bar, the
// room, compact stats and Uma Musume-style commands. 練習 opens the five trainings; the first tap on
// a choice previews it (gains, stamina, failure rate) and a second tap on the same button decides.
// 休む・お出かけ・下見 work the same way. Town talks, the 3-year plan and the menu open on demand.
let homeMode='main',homePick=null;
function homeDate(){const d=gameDate(s);return s.turn===72?'3年目・育成完了':`${d.year}年目 ${d.month}${s.storyVersion>=2?'か月目':'月'} ${d.half}`;}
function homeBar(){const comp=currentCompetition(s),next=nextRace();return `<header class="home-bar"><div class="home-when"><strong>${homeDate()}</strong><small>${s.turn} / 72ターン</small></div>${tab!=='training'?'<button class="home-chip" data-tab="training">← 育成へ</button>':`<button class="home-chip" data-action="plan" aria-label="3年間の大会予定を見る">${comp?'<b>大会の日</b>':next?`${esc(normal(next.title))}<b>あと${Math.max(0,next.turn-s.turn)}</b>`:'大会予定'}</button>`}<button class="home-menu-button" data-action="menu" aria-label="メニュー">≡</button></header>`;}
// After a training: a line that opens with 「…」 is the hero's own voice; any other line is narration of the
// moment and is shown as it is under 「きょうの練習」 (#30 side stories, owner 2026-10-25).
function trainingMoment(){const r=s.lastAction?.text?.match(/^[^、]+、(?:失敗……能力は上がらなかった。|友情練習！|大成功！|成功！)(?: \S+＋\d+)? (.+)$/)?.[1]||'';const q=r.match(/^「([^」]+)」/);return q?{voice:true,text:q[1]}:r?{voice:false,text:r}:null;}
function homeSay(){if(s.phase!=='training'||!s.lastAction)return message();const m=trainingMoment();return m?m.text:(s.lastAction.text?.match(/「([^」]+)」/)?.[1]||'今日の足あとを、次の一歩へ。');}
// #30 (owner 2026-10-30): the room fills the screen, so its canvas follows the box it is shown in (sharp on phones).
function fitHomeCanvas(cv){const r=cv?.getBoundingClientRect?.();if(!r||!(r.width>0&&r.height>0))return cv;const dpr=Math.min(2,globalThis.devicePixelRatio||1),w=Math.round(r.width*dpr),h=Math.round(r.height*dpr);if(cv.width!==w||cv.height!==h){cv.width=w;cv.height=h;}return cv;}
function homeRoom(){return `<section class="home-room-one" aria-label="ひまわりのおへや"><div class="scene-wrap"><canvas id="scene" width="768" height="432" aria-label="温かな木の部屋で過ごす${esc(individualName(s))}"></canvas><span class="scene-name">${esc(individualName(s))}</span></div></section>`;}
function homeStats(gains=null){return `<section class="home-stats" aria-label="能力">${STAT_NAMES.map((name,i)=>`<div class="hs" data-stat="${i}"><small>${name}</small><b class="stat-value">${s.stats[i]}</b><em class="stat-grade">${grade(s.stats[i])}</em>${gains?.[i]?`<i class="hs-up">＋${gains[i]}</i>`:''}<span class="hs-bar"><i style="width:${s.stats[i]}%"></i></span></div>`).join('')}</section><div class="home-vitals"><span>体力</span><span class="meter"><i style="width:${s.energy}%"></i></span><b>${s.energy}</b><span>やる気 <b>${isLegacy(s)?s.mood:MOOD_NAMES[moodLevel(s.mood)]}</b></span><span>きずな <b>${s.trainerBond}</b></span></div>`;}
function choiceOff(t){const next=nextRace();return isLegacy(s)&&['outing','scout'].includes(t.key)||t.key==='scout'&&(!next||s.scouted?.includes(next.id));}
// Friends who came to this training show their faces on the button (#30 B2, owner 2026-10-25).
function friendFaces(t){const n=t.target!==undefined&&!isLegacy(s)?trainingNPCs(s,t.key):[];return n.length?`<span class="friend-faces" aria-hidden="true">${n.slice(0,3).map(f=>`<i><canvas width="60" height="60" data-friend-badge="${f.portraitId||f.id}"></canvas></i>`).join('')}</span>`:'';}
function choiceButton(t,cls,label=t.name){const picked=homePick===t.key,friends=t.target!==undefined&&!isLegacy(s)?trainingNPCs(s,t.key):[];return `<button class="${cls}${picked?' picked':''}${friends.length?' with-friends':''}" ${picked?`data-train="${t.key}"`:`data-train-pick="${t.key}"`} ${choiceOff(t)?'disabled':''} aria-pressed="${picked}" aria-label="${t.name}${friends.length?`（${friends.map(f=>f.name).join('・')}が来ている）`:''}${picked?'に決定':'の内容を見る'}">${friendFaces(t)}<img class="pixel-icon" src="./assets/home-ui-v24/action-${t.key}.png" alt=""><span>${label}</span>${picked?'<em>もう一度で決定</em>':''}</button>`;}
function pickDetail(t){const active=t.target!==undefined,info=active?trainingPreview(s,t.key):null,helpers=active?trainingNPCs(s,t.key):[],risk=active?failureChance(s,t.key):0;
 const gains=active?info.gains.map((v,i)=>v?`<span class="chip${i===t.target?' main':''}">${STAT_NAMES[i]} ＋${v}</span>`:'').join(''):t.key==='scout'?'<span class="chip main">次の大会のゾーンがわかる</span>':`<span class="chip main">体力 ＋${Math.min(100-s.energy,t.key==='rest'?46:18)}</span>${t.key==='outing'?'<span class="chip">やる気 1段階↑</span>':''}`;
 const effects=active?`${helpers.length?`友情効果 ＋${Math.round(info.friendshipBonus*100)}% / `:''}大成功時 ${STAT_NAMES[t.target]}＋${info.greatGains[t.target]}${info.accumulating?' / 小さな成長を蓄積中':''}`:t.key==='rest'?'体力の上限100まで回復 / きずな＋6':t.key==='outing'?'きずな＋4 / 上限を超えて回復しません':'特殊ゾーンの種類と順番がわかる';
 return `<div class="pick-detail" role="status"><div class="pick-head"><b>${t.name}</b><span>体力 ${active?'−'+trainingCost(s,t.key):'消費なし'}</span><span class="${risk>=25?'risk':''}">${active?`失敗率 ${risk}%`:'失敗なし'}</span></div><div class="pick-gains">${gains}</div><small>${helpers.length&&!isLegacy(s)?`<b class="friend-help">仲間の支え：体力の消費−${Math.round((1-FRIEND_COST)*100)}%・失敗率−${FRIEND_FAIL}</b> `:''}${helpers.length?helpers.map(n=>`${n.name}と練習（友情 ${s.npcRelations[n.id]||0}→${Math.min(100,(s.npcRelations[n.id]||0)+20)}）`).join('・'):active?'ひとりで練習 · 幼なじみが見守る':esc(t.sub)} / ${effects}${s.social?.boost?.key===t.key?' / 改良道具＋10%':''}</small></div>`;}
function homeCommands(){
 if(s.phase!=='training')return training();
 const work=TRAININGS.filter(t=>t.target!==undefined),care=TRAININGS.filter(t=>t.target===undefined),picked=TRAININGS.find(t=>t.key===homePick);
 if(homeMode==='train')return `<section class="home-panel train-panel" aria-label="練習をえらぶ">${picked?.target!==undefined&&picked?pickDetail(picked):'<p class="pick-hint">顔の出ている練習には仲間が来ています（体力の消費−40%・失敗しにくい）。1回押すと中身、もう一度で決定。</p>'}<div class="train-row">${work.map(t=>choiceButton(t,'tr')).join('')}</div><button class="home-back secondary" data-home="main">← もどる</button></section>`;
 const towns=townOffer(s).length+sideOffers(s).length;
 return `<section class="home-panel" aria-label="今日の行動">${picked&&picked.target===undefined?pickDetail(picked):''}<div class="home-commands"><button class="cmd cmd-train" data-home="train"><img class="pixel-icon" src="./assets/home-ui-v24/action-speed.png" alt=""><span>練習</span></button>${care.map(t=>choiceButton(t,'cmd',{rest:'休む',outing:'お出かけ',scout:'下見'}[t.key])).join('')}<button class="cmd" data-action="town"><span>町へ</span>${towns?`<i class="cmd-badge">${towns}</i>`:''}</button><button class="cmd" data-tab="ability"><span>能力</span></button></div></section>`;}
function lastTrainingNotes(){if(!s.lastAction||s.turn<=0)return '';const note=trainingNotebook(s),recent=s.lastAction.gains?.map((value,i)=>value>0?`${STAT_NAMES[i]} +${value}`:null).filter(Boolean)||[];
 return `<aside class="training-feedback" aria-label="直前の行動結果"><p>${esc(normal(s.lastAction.text||''))}</p><div>${recent.length?recent.map(x=>`<span class="effect-chip">${esc(x)}</span>`).join(''):'<span class="effect-chip">能力変化なし</span>'}</div></aside>${note?`<details class="home-notebook"><summary>練習ノート・詳しい振り返り</summary><aside class="coach-notebook"><b>幼なじみの練習ノート</b><p>${esc(note.coach)}</p>${note.changes.map(x=>`<p>${esc(x)}</p>`).join('')}<small>体力 ${note.energyDelta>=0?'+':''}${note.energyDelta} / きずな ＋${note.bondDelta}</small>${note.comparison?`<p>${esc(note.comparison)}</p>`:''}${note.learned.map(x=>`<p>${esc(x)}</p>`).join('')}</aside></details>`:''}`;}
function home(){if(s.phase!=='training'){homeMode='main';homePick=null;}
 const preview=homeMode==='train'?TRAININGS.find(t=>t.key===homePick&&t.target!==undefined):null;
 return `${!isLegacy(s)&&!(s.storyVersion>=2)?`<aside class="save-notice"><b>以前の育成を、そのまま続行中。</b>能力と結果を保つため、新しい物語とライバルは次の育成から登場します。${button('restart','記録を残して新しい物語をはじめる','secondary')}</aside>`:''}${isLegacy(s)?`<aside class="save-notice"><b>旧版の育成を引き継いでいます。</b>結果とseedを保つため、この育成は当時の大会で続行します。${button('restart','新仕様の育成をはじめる','secondary')}</aside>`:''}<section class="home-one" data-state="${s.phase}" data-mode="${homeMode}" data-pick="${homePick?1:0}" aria-label="育成ホーム">${homeRoom()}<div class="home-top">${homeStats(preview?trainingPreview(s,preview.key).gains:null)}${s.phase==='training'&&homeMode==='main'&&!homePick?`<p class="home-say"><small>${trainingMoment()?.voice===false?'きょうの練習':`${esc(individualName(s))} のきもち`}</small>${esc(homeSay())}</p>`:''}</div><div class="home-bottom">${hasPendingDialogue(s)?`<section class="conversation-entry"><b>物語のつづきが待っています。</b>${button('dialogue-open','会話を再開 →')}</section>`:''}${homeCommands()}</div></section>`;}
// 能力 and 戦績 fit one screen too (#30, owner 2026-10-25): each page splits into small tabs.
let abilityTab='stats',recordTab='races';
function subTabs(kind,current,list){return `<div class="sub-tabs" role="tablist">${list.map(([id,name])=>`<button class="sub-tab ${current===id?'active':''}" role="tab" aria-selected="${current===id}" data-sub-tab="${kind}:${id}">${name}</button>`).join('')}</div>`;}
function abilities(){const contacts=s.storyVersion>=2?knownContacts(s):[...NPCS,...TOWN_CAST.filter(n=>['seedshop','tanuki','beaver'].includes(n.id)),...ZODIAC_CAST.filter(n=>!NPCS.some(x=>x.id===n.id)&&(s.events?.storyProgress['world-met']||s.npcRelations[n.id]))];
 const body=abilityTab==='bonds'?`<div class="relationship-card"><h3>トレーナーとのきずな：${s.trainerBond}</h3><p>トレーナーとの信頼。NPCの友情度とは別の値です。</p><div class="bond-list">${contacts.map(n=>`<p>${n.name}との友情　${s.npcRelations[n.id]||0} / 100</p>`).join('')}</div><small>仲間と約5回の練習でMAX。成長ボーナスは最大＋25%。</small></div>`:abilityTab==='last'?lastTrainingNotes()||'<p class="empty-state">まだ行動していません。</p>':`${statRows()}<div class="individuality-grid"><div class="individuality-card"><h2>性格：${personalityOf(s).name}</h2><p>${personalityOf(s).description}</p></div>${(s.talentRule==='random'?ownedTalents(s):[talentOf(s)]).map((t,i)=>`<div class="individuality-card${t.gold?' gold':''}"><h2>${i?'レアで手に入れた才能':'才能'}：${esc(t.name)}</h2><p>${esc(t.description)}</p></div>`).join('')}</div><h3>習得スキル</h3><p>${s.skills.map(i=>STAT_NAMES[i]+'のコツ').join(' / ')||'各能力58以上で習得します。'}</p><p class="micro-note">迷路＝きようさ、早食い＝食欲、勉強＝かしこさ。体力の低下は1回だけ計算し、疲労を重ねて引きません。</p>`;
 return `<section class="panel wide-panel one-page"><h1>能力と、きみらしさ</h1>${subTabs('ability',abilityTab,[['stats','能力・性格'],['bonds','きずな・友情'],['last','前回の行動']])}${body}</section>`;}
function records(){const rows=[...s.legacyRaces,...s.races].reverse();
 const body=recordTab==='chart'?progressChartMarkup([...s.legacyRaces,...s.races]):recordTab==='notes'?s.log.slice(0,10).map(l=>`<div class="log-entry"><small>${l.turn}ターン</small><span>${esc(l.text)}</span></div>`).join('')||'<p class="empty-state">まだ記録はありません。</p>':rows.map(r=>`<div class="history-card"><div><h3>${esc(normal(r.title))}</h3><p>${r.turn??r.year*24}ターン / ${r.entrants}匹 / ${r.standings.find(x=>x.id==='player')?.total.toFixed(2)}秒</p></div><b class="rank">${r.rank}位</b><button class="secondary" data-race-record="${esc(r.id)}">結果</button></div>`).join('')||'<p class="empty-state">最初の大会は、これから。</p>';
 return `<section class="panel wide-panel one-page"><h1>戦績</h1>${subTabs('records',recordTab,[['races','大会'],['chart','成長グラフ'],['notes','育成ノート']])}${body}</section>`;}
function render(){
 $('game').innerHTML=`${artReviewEnabled()?'<aside class="save-notice"><b>新アートの確認用見本</b> 全画面への正式採用前です。<a href="?">通常表示へ</a></aside>':''}${titleMode?'':homeBar()}${loaded.notice?`<aside class="save-notice" role="status">${esc(loaded.notice)}</aside>`:''}${titleMode?title():`<div id="view">${tab==='training'?home():tab==='ability'?abilities():records()}</div>`}`;
 document.body.dataset.screen=titleMode?'title':'training';portraits();drawHomeScene(fitHomeCanvas($('scene')),partnerIndex(s),scenePose);save();
}
// Per-run talent (#30 R1, owner 2026-10-26): three candidates from all nine, fixed by the run's seed.
function revealTalent(){const t=talentOf(s);openModal('talent','才能が目覚めた！',`<div class="talent-reveal"><small>${esc(individualName(s))}の才能</small><div class="talent-card talent-card-reveal"><b>${esc(t.name)}</b><span>${esc(t.description)}</span></div><p>育成のとちゅう、レアイベントで新しい才能が手に入ることもあります。金の才能は、少し強い特別な才能です。</p></div>${button('talent-ok','この才能で、はじめる →','primary full')}`,false);}
function choose(draftName=''){const candidates=ownedCandidates(data.profile);if(!candidates.some(h=>h.id===pick))pick=candidates[0]?.id;openModal('choose','いっしょに走る、一匹を',`<h3>きみのパートナーは？</h3><p>${isLegacy(s)?'性格と才能は別々。所持情報は、次の育成にも残ります。':'性格はその子のまま。才能は、育成ごとにランダムで目覚めます。とちゅうのレアイベントで増えることも。'}</p><div class="partner-grid">${candidates.map(h=>{const p=PARTNERS.find(p=>p.id===h.characterId);return `<button class="partner-card ${pick===h.id?'selected':''}" data-pick="${esc(h.id)}" aria-pressed="${pick===h.id}"><canvas width="66" height="60" data-portrait="${PARTNERS.indexOf(p)}"></canvas><h3>${esc(h.name||p.name)}</h3><small>${p.coat}</small><div class="partner-traits"><b>${personalityOf(h).name} / ${isLegacy(s)?talentOf(h).name:'才能は、はじめてのお楽しみ'}</b><span>${p.desc}</span></div></button>`;}).join('')}</div><label class="name-field">個体名（空欄なら今の名前）<input id="partner-name" maxlength="40" autocomplete="off" placeholder="好きな名前をつけてもOK"></label>${candidates.length?button('start','この子と、はじめる →','primary full'):'<p>育成可能な所持個体がありません。旧版の所持情報は保管されています。</p>'}`);$('partner-name').value=draftName;}
// 図鑑 (#30, owner 2026-10-25): endings, stories, town visits, the hall of the twelve and personal bests.
// Seen entries can be re-read as a preview (no effects); unseen ones show ？？？ and a hint.
let albumTab='endings',albumKind='daily',albumPage=0,albumReturn=false;
const ALBUM_PAGE=10;
function albumTile(e,kind,id=e.id){return e.run?`<button class="album-tile" data-album-read="${kind}|${esc(id)}"${hasPendingDialogue(s)?' disabled':''}><b>${esc(e.title)}</b><small>読み返す ▶</small></button>`:`<div class="album-tile locked"><b>？？？</b><small>${esc(e.hint)}</small></div>`;}
function albumPager(total){const pages=Math.max(1,Math.ceil(total/ALBUM_PAGE));albumPage=Math.min(albumPage,pages-1);return pages>1?`<div class="album-pager"><button class="secondary" data-album-page="${albumPage-1}"${albumPage?'':' disabled'}>◀</button><span>${albumPage+1} / ${pages}</span><button class="secondary" data-album-page="${albumPage+1}"${albumPage<pages-1?'':' disabled'}>▶</button></div>`:'';}
function albumBody(){
 const data2={...data,activeRun:s},a=albumData(data2),n=albumCounts(a),pageOf=list=>list.slice(albumPage*ALBUM_PAGE,(albumPage+1)*ALBUM_PAGE);
 const tabs=[['endings','エンディング',n.endings],['stories','小話',n.stories],['town','町',n.town],['hall','殿堂'],['bests','記録']];
 let body='';
 if(albumTab==='endings')body=`<div class="album-grid">${a.endings.map(e=>albumTile(e,'ending')).join('')}</div>`;
 else if(albumTab==='stories'){const list=albumKind==='daily'?a.dailies:a.sides;body=`<div class="album-sub">${[['daily',`日常 ${a.dailies.filter(x=>x.run).length}/${a.dailies.length}`],['side',`寄り道 ${a.sides.filter(x=>x.run).length}/${a.sides.length}`]].map(([k,l])=>`<button class="${albumKind===k?'active':''}" data-album-kind="${k}" aria-pressed="${albumKind===k}">${l}</button>`).join('')}</div><div class="album-grid">${pageOf(list).map(e=>albumTile(e,albumKind)).join('')}</div>${albumPager(list.length)}${albumKind==='side'?'<p class="album-note">寄り道の話は、その時期に「町へ」の一覧から読めます。</p>':''}`;}
 else if(albumTab==='town')body=`<div class="album-town">${a.town.map(f=>`<div class="album-friend"><b>${esc(f.name)}</b><span>${f.steps.map(st=>st.run?`<button data-album-read="town|${f.id}:${st.n}"${hasPendingDialogue(s)?' disabled':''} aria-label="${esc(f.name)}とひと息 ${st.n}回目を読み返す">${st.n}</button>`:`<i title="${esc(f.hint)}">？</i>`).join('')}</span></div>`).join('')}</div><p class="album-note">町で会うたびに、続きの話が増えます（${TOWN_STEPS}回まで）。ぽてちは出会ったあと、ネコは新しい物語でネコに会ったあとに会えます。</p>`;
 else if(albumTab==='hall'){const h=hall(data2).reverse(),list=pageOf(h);body=h.length?`<ol class="album-hall">${list.map(x=>`<li><span class="gen">第${x.generation}代</span><b>${esc(x.name)}</b><small>${esc(x.hero)}・世界${x.rank??'—'}位${Number.isFinite(x.time)?`・${x.time.toFixed(2)}秒`:''}${x.cat?`・ネコ${x.cat.rank}位`:''}${x.date?`・${x.date.getFullYear()}/${x.date.getMonth()+1}/${x.date.getDate()}`:''}</small></li>`).join('')}</ol>${albumPager(h.length)}`:'<p class="empty-state">まだ十二支になった子はいません。最初の一匹を、この殿堂へ。</p>';}
 else{const b=bests(data2);body=`<div class="album-bests"><p><span>育成</span><b>${b.runs}回</b><span>十二支</span><b>${b.champions}回</b><span>世界大会</span><b>${b.worldRuns}回</b></p><p><span>世界大会の最高</span><b>${b.bestRank?b.bestRank+'位':'—'}</b><span>最速</span><b>${Number.isFinite(b.bestTime)?b.bestTime.toFixed(2)+'秒':'—'}</b></p><h4>主人公ごと</h4>${b.heroes.map(x=>`<p><span>${esc(x.name)}</span><b>${x.runs?`${x.result}${x.bestRank?`（世界${x.bestRank}位）`:''}`:'まだ'}</b><small>${x.runs}回</small></p>`).join('')}<h4>仲間の友情（いちばん高かったとき）</h4><div class="album-friends">${b.friends.map(x=>`<p><span>${esc(x.name)}</span><b>${x.best}</b></p>`).join('')}</div></div>`;}
 return `<div class="album" data-tab="${albumTab}"><div class="album-tabs" role="tablist">${tabs.map(([k,l,c])=>`<button role="tab" class="${albumTab===k?'active':''}" aria-selected="${albumTab===k}" data-album-tab="${k}">${l}<small>${c?`${c[0]}/${c[1]}`:'&nbsp;'}</small></button>`).join('')}</div>${hasPendingDialogue(s)?'<p class="album-note">会話のつづきを読んだあとに、読み返せます。</p>':''}${body}</div>`;
}
function openAlbum(){openModal('album','図鑑',albumBody());}
function archive(){const rows=[...data.archives].reverse();openModal('archive','育成記録',`<h3>小さな足あと、ずっと。</h3>${rows.map(r=>`<div class="history-card"><div><h3>${esc(individualName(r))}</h3><p>${r.turn} / 72ターン · ${r.ending==='zodiac_member'?'十二支入り':r.ending==='domestic_loss'?'国内予選・復活戦敗退':r.ending==='representative_loss'?'最終代表戦敗退':r.ending==='zodiac_loss'?'世界大会への挑戦':'途中の育成記録'}</p><p>${r.stats.map((v,i)=>STAT_NAMES[i]+v).join(' / ')}</p></div><button class="secondary" data-archive-id="${esc(r.id)}">記録を読む</button></div>`).join('')||'<p class="empty-state">まだ育成記録はありません。</p>'}`);}
function archiveDetail(run){openModal('archive-detail',esc(individualName(run))+'の育成記録',`${statRows(run)}<h3>${run.ending==='zodiac_member'?'十二支入り達成':'小さな足あと'}</h3>${run.races.map(r=>`<div class="history-card"><div><h3>${esc(normal(r.title))}</h3><p>${r.entrants}匹中${r.rank}位 / ${r.standings.find(x=>x.id==='player')?.total.toFixed(2)}秒</p></div></div>`).join('')}${button('archive','一覧にもどる','secondary')}`);}
function label(row){return row.id==='player'?row.name:normal(row.name);}
function twelveMarkup(r){return `<section class="selected-twelve"><h4>十二支に選ばれた12匹</h4><p>${r.rank<=12?'あなたも、新しい十二支へ！':'あと一歩。選出された仲間へ、拍手を。'}</p><div>${r.standings.slice(0,12).map((x,i)=>`<span class="${x.id==='player'?'is-player':''}"><b>${i+1}</b> ${esc(label(x))}</span>`).join('')}</div></section>`;}
function ceremonyMarkup(r,animate=false,twelve=true){const theme=raceTheme(r),reaction=r.rank===1?'やった！ 最後まで走りきった！':r.kind==='zodiac'&&r.rank<=12?'十二支入り。小さな胸を、誇らしく。':r.rank<=3?'あと一歩。でも、この走りを誇ろう。':'最後まで、よく走った！ 次はもっと前へ。';return `<section class="ceremony ceremony-${theme.id} ${animate?'ceremony-initial':''}" aria-label="確定結果の表彰式"><canvas id="ceremony-stage" width="768" height="216" aria-hidden="true"></canvas><p class="ceremony-title">${theme.id==='shrine'?'星月の社で、いま結果発表':'小さな足の、大きな表彰式'}</p><div class="ceremony-winners">${r.standings.slice(0,3).map((x,i)=>`<article class="ceremony-winner" style="--reveal:${i*.3}s"><b>${i+1}位</b><canvas width="192" height="168" data-award-id="${esc(x.id)}" aria-label="${esc(label(x))}"></canvas><strong>${esc(label(x))}</strong><span>${x.total.toFixed(2)} 秒</span></article>`).join('')}</div>${r.kind==='zodiac'&&twelve?twelveMarkup(r):''}<div class="ceremony-hero"><canvas width="192" height="168" data-award-id="player" aria-hidden="true"></canvas><p><b>あなたの確定順位：${r.rank}位 / ${r.entrants}匹</b><br>${reaction}</p></div></section>`;}
function ceremonyArt(r){drawAwardsStage($('ceremony-stage'),r);for(const canvas of document.querySelectorAll('[data-award-id]')){const row=r.participants?.find(x=>x.id===canvas.dataset.awardId)||r.standings.find(x=>x.id===canvas.dataset.awardId);drawAwardPortrait(canvas,row,partnerIndex(s),row.id==='player'?(r.rank===1||r.kind==='zodiac'&&r.rank<=12?'joy':'neutral'):'neutral');}}
// One-screen result (#30, owner 2026-10-25): rank, time and outcome on top, then tabs — 表彰
