 const next=r.kind==='zodiac'?'エンディングへ':r.kind==='representative'?(r.rank===1?'世界十二支決定戦へ':'敗北エンディングへ'):r.kind==='selection'?(pass?'次の1年へ':'直後の敗者復活戦へ'):r.kind==='repechage'?(pass?'次の1年へ':'敗北エンディングへ'):'育成をつづける';
