 const panel=detail?analysis:resultTab==='table'?`<div class="result-list ${resultAll?'all':''}" tabindex="0" aria-label="正式順位">${resultRows(r)}</div>${r.standings.length>8?button('result-all',resultAll?'上位と自分のまわりだけ':`全員（${r.standings.length}匹）の順位を見る`,'secondary full'):''}`:resultTab==='review'?review:resultTab==='twelve'&&final?twelveMarkup(r):ceremonyMarkup(r,animateCeremony,!final);
 openModal(history?'history-result':'result','レース結果',`<div class="res-one${detail?' res-detail':''}"><div class="result-heading res-top"><div class="eyebrow">OFFICIAL RESULT · ${esc(normal(r.title))}</div><div class="res-rank"><div class="big-rank"><strong>${r.rank}</strong> 位 <span>/ ${r.entrants}匹</span></div><p class="finish-time">${time.toFixed(2)} 秒</p></div><h3>${outcome}</h3>${r.kind==='ordinary'?'<p class="res-reward">全能力＋1・体力＋35（順位にかかわらず育成はつづく）</p>':''}</div>${detail?'':tabs}<div class="res-panel">${panel}</div><div class="result-actions">${button(detail?'analysis-close':'analysis',detail?'概要にもどる':'詳細分析','secondary')}${history?button('close','記録にもどる'):s.phase==='results'?button('accept-race',next+' →'):button('close','育成にもどる')}</div></div>`);
 if(!detail&&resultTab==='award')ceremonyArt(r);if(animateCeremony)raceCue('award');
