 if(b.dataset.train){const before=eventSnapshot();if(train(s,b.dataset.train)){homeMode='main';homePick=null;data.presentation={...data.presentation,trainingReview:{runId:s.id,turn:s.turn,key:b.dataset.train,energyBefore:before.energy,moodBefore:before.mood,bondBefore:before.trainerBond}};render();trainingResult();}return;}
